action.code:
if (face->info().processed) return;
face->info().processed = true;
for (int i = 0; i < 3; ++i) vertices.push_back(face->vertex(i));
for (int i = 0; i < 3; ++i) {
    if (i == edge) continue;
    auto nbr = face->neighbor(i);
    if (nbr && nbr->info().interior && !nbr->info().processed) {
        get_face_boundary_vertices(nbr, i, vertices);
    }
}

